steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        teams(name: \"Web\") {
          id
          name
          issues(filter: {
            search: { _or: [{ title: { contains: \"login redirect\" } }, { description: { contains: \"login redirect\" } }] },
            createdAt: { gte: \"2024-09-10T00:00:00.000Z\", lte: \"2024-09-10T23:59:59.999Z\" }
          }) {
            id
            identifier
            title
            description
            createdAt
            state { name }
            assignee { name }
            creator { name }
          }
        }
      }
    "
  }'
